// Apply the same frozen accounting correction to full evidence and paged rows.
// Accounting v1's legacy Claude fallback repeated cache creation as cache reads.
func (s *Service) correctEventAccounting(ctx context.Context, events []Event) error {
	priceCache := map[string]model.ModelPrice{}
	for i := range events {
		e := &events[i]
		if e.AccountingVersion >= 2 || e.Provider != "claude" {
			continue
		}
		read := max(int64(0), e.Tokens.Input-e.RawInput-e.Tokens.CacheCreation)
		if read == e.Tokens.Cached {
			continue
		}
		e.OriginalAccounting = &OriginalAccounting{Cached: e.Tokens.Cached, CostNano: e.CostNano, Reason: "v2: normalized Claude cache reads = total input - raw input - cache creation; legacy cached fallback is not an extra read"}
		e.Tokens.Cached, e.AccountingVersion = read, 2
		if e.PriceID == "" {
			continue
		}
		p, ok := priceCache[e.PriceID]
		if !ok {
			var raw string
			if err := s.db.QueryRowContext(ctx, "SELECT payload FROM analytics_prices WHERE id=?", e.PriceID).Scan(&raw); err != nil {
				return err
			}
			var frozen struct {
				Price model.ModelPrice `json:"price"`
			}
			if err := json.Unmarshal([]byte(raw), &frozen); err != nil {
				return err
			}
			p = frozen.Price
			priceCache[e.PriceID] = p
		}
		nano := eventCost(*e, p)
		e.CostNano = &nano
	}
	return nil
}
